package com.focusflow.api.dto; import com.focusflow.api.entity.*; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; public final class ApiDtos { private ApiDtos(){} public record Register(@NotBlank String name,@Email String email,@Size(min=8) String password){} public record Login(@Email String email,@NotBlank String password){} public record Auth(String token,String name,String email){} public record TaskRequest(@NotBlank String title,String description,Task.Status status,Task.Priority priority,String category,LocalDate dueDate,LocalTime dueTime,Instant reminder){} public record TaskResponse(String id,String title,String description,Task.Status status,Task.Priority priority,String category,LocalDate dueDate,LocalTime dueTime,Instant reminder,Instant completedAt,Instant createdAt,Instant updatedAt){} public record CategoryRequest(@NotBlank String name,String color){} public record CategoryResponse(String id,String name,String color){} public record SyncRequest(List<TaskRequest> tasks,List<CategoryRequest> categories){} public record SyncResponse(List<TaskResponse> tasks,List<CategoryResponse> categories){} }
